import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.CWgsre3x.js";const c=JSON.parse('{"title":"Συχνές ερωτήσεις","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/faq.md","filePath":"el/help/faq.md"}'),i={name:"el/help/faq.md"};function h(o,a,s,n,d,p){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="συχνες-ερωτησεις" tabindex="-1">Συχνές ερωτήσεις <a class="header-anchor" href="#συχνες-ερωτησεις" aria-label="Permalink to &quot;Συχνές ερωτήσεις&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Αναφορά v0.7.26, όχι έλεγχος ζωντανής εγκατάστασης ή έγκριση εμπορικής λειτουργίας. Ελέγξτε έκδοση, δικαιώματα, ρυθμίσεις και αποδοχή.</p></div><h2 id="χρειαζεται-εγκατασταση-εφαρμογης-στο-προσωπικο" tabindex="-1">Χρειάζεται εγκατάσταση εφαρμογής στο προσωπικό; <a class="header-anchor" href="#χρειαζεται-εγκατασταση-εφαρμογης-στο-προσωπικο" aria-label="Permalink to &quot;Χρειάζεται εγκατάσταση εφαρμογής στο προσωπικό;&quot;">​</a></h2><p>Δεν απαιτείται εγγενής εφαρμογή για πρόσβαση μέσω browser. Χρησιμοποιήστε εγκεκριμένη εγκατάσταση HTTPS και υποστηριζόμενες συσκευές· συμβατότητα κινητού και GPS ελέγχονται χωριστά. <a href="/el/system-requirements/">Απαιτήσεις συστήματος</a></p><h2 id="πως-δημιουργουμε-λογαριασμο-διαχειριστη-χειριστη-η-οδηγου" tabindex="-1">Πώς δημιουργούμε λογαριασμό διαχειριστή, χειριστή ή οδηγού; <a class="header-anchor" href="#πως-δημιουργουμε-λογαριασμο-διαχειριστη-χειριστη-η-οδηγου" aria-label="Permalink to &quot;Πώς δημιουργούμε λογαριασμό διαχειριστή, χειριστή ή οδηγού;&quot;">​</a></h2><p>Ζητήστε εξουσιοδοτημένη δημιουργία στο backend με ελάχιστο απαιτούμενο ρόλο. Η εγγραφή οδηγού δεν δημιουργεί αυτόματα λογαριασμό ή σύνδεση με αναθέσεις. Το προσωπικό χρησιμοποιεί ατομικό email και κωδικό. Δημόσια αίτηση δεν δημιουργεί λογαριασμό. <a href="/el/plus/staff-administration.html">Προσωπικό</a></p><h2 id="μπορει-επιβατης-να-κανει-κρατηση-χωρις-email" tabindex="-1">Μπορεί επιβάτης να κάνει κράτηση χωρίς email; <a class="header-anchor" href="#μπορει-επιβατης-να-κανει-κρατηση-χωρις-email" aria-label="Permalink to &quot;Μπορεί επιβάτης να κάνει κράτηση χωρίς email;&quot;">​</a></h2><p>Ναι. Χρησιμοποιήστε πραγματικό τηλέφωνο και αφήστε το email κενό αν δεν δόθηκε. Μην επινοείτε διεύθυνση. Η σύνδεση προσωπικού είναι διαφορετική. <a href="/el/tutorials/phone-only-booking.html">Κράτηση μόνο με τηλέφωνο</a></p><h2 id="ποιες-υπηρεσιες-μπορουμε-να-ρυθμισουμε" tabindex="-1">Ποιες υπηρεσίες μπορούμε να ρυθμίσουμε; <a class="header-anchor" href="#ποιες-υπηρεσιες-μπορουμε-να-ρυθμισουμε" aria-label="Permalink to &quot;Ποιες υπηρεσίες μπορούμε να ρυθμίσουμε;&quot;">​</a></h2><p>Υποστηρίζονται απλή μεταφορά, μεταφορά με επιστροφή, ωριαία υπηρεσία οδηγού και ιδιωτικές εκδρομές. Ρυθμίστε αγορές, τοποθεσίες, χωρητικότητα και τιμές και δοκιμάστε κάθε υπηρεσία που πωλείται. <a href="/el/getting-started/first-reservation.html">Πρώτη κράτηση</a></p><h2 id="γιατι-απαιτειται-χειροκινητη-προσφορα" tabindex="-1">Γιατί απαιτείται χειροκίνητη προσφορά; <a class="header-anchor" href="#γιατι-απαιτειται-χειροκινητη-προσφορα" aria-label="Permalink to &quot;Γιατί απαιτείται χειροκίνητη προσφορά;&quot;">​</a></h2><p>Ελλιπής ή μη έγκυρος ναύλος δεν σημαίνει δωρεάν διαδρομή. Ελέγξτε κατεύθυνση, ώρα, κατηγορία και κανόνες τιμολόγησης. Χρησιμοποιήστε εξουσιοδοτημένη χειροκίνητη προσφορά όταν λείπει έγκυρη τιμή. <a href="/el/plus/manual-quotations.html">Χειροκίνητες προσφορές</a></p><h2 id="μπορουν-διαφορετικοι-οδηγοι-να-εκτελεσουν-μεταβαση-και-επιστροφη" tabindex="-1">Μπορούν διαφορετικοί οδηγοί να εκτελέσουν μετάβαση και επιστροφή; <a class="header-anchor" href="#μπορουν-διαφορετικοι-οδηγοι-να-εκτελεσουν-μεταβαση-και-επιστροφη" aria-label="Permalink to &quot;Μπορούν διαφορετικοί οδηγοί να εκτελέσουν μετάβαση και επιστροφή;&quot;">​</a></h2><p>Υποστηρίζονται ανεξάρτητα σκέλη. Ελέγξτε χωριστά ανάθεση, χρόνο, χωρητικότητα, όχημα και πρόοδο. <a href="/el/plus/chauffeur-workspace.html">Χώρος οδηγού</a></p><h2 id="γιατι-απορριφθηκε-η-αναθεση" tabindex="-1">Γιατί απορρίφθηκε η ανάθεση; <a class="header-anchor" href="#γιατι-απορριφθηκε-η-αναθεση" aria-label="Permalink to &quot;Γιατί απορρίφθηκε η ανάθεση;&quot;">​</a></h2><p>Ελέγξτε κατάσταση κράτησης και προσφοράς, πλήρες διάστημα, βάρδια ή απουσία, συντήρηση, χωρητικότητα και ανταγωνιστικές αναθέσεις. Ανανεώστε μετά από σύγκρουση· μην επιβάλλετε ανάθεση. <a href="/el/plus/dispatch-schedule.html">Πρόγραμμα</a></p><h2 id="μπορω-να-εισπραξω-μερος-των-μετρητων-και-να-τα-παραδωσω-αργοτερα" tabindex="-1">Μπορώ να εισπράξω μέρος των μετρητών και να τα παραδώσω αργότερα; <a class="header-anchor" href="#μπορω-να-εισπραξω-μερος-των-μετρητων-και-να-τα-παραδωσω-αργοτερα" aria-label="Permalink to &quot;Μπορώ να εισπράξω μέρος των μετρητών και να τα παραδώσω αργότερα;&quot;">​</a></h2><p>Καταγράψτε μόνο πραγματική είσπραξη στην εξουσιοδοτημένη ροή. Ελέγξτε υπόλοιπο και οδηγό είσπραξης. Επιβεβαιώστε χωριστά φυσική παράδοση στο γραφείο μετά την πραγματική παράδοση. <a href="/el/plus/cash-management.html">Μετρητά</a></p><h2 id="ειναι-ηδη-ενεργες-οι-online-πληρωμες" tabindex="-1">Είναι ήδη ενεργές οι online πληρωμές; <a class="header-anchor" href="#ειναι-ηδη-ενεργες-οι-online-πληρωμες" aria-label="Permalink to &quot;Είναι ήδη ενεργές οι online πληρωμές;&quot;">​</a></h2><p>Δεν επιβεβαιώνεται ζωντανή ενεργοποίηση παρόχου. Απαιτούνται εγκεκριμένα διαπιστευτήρια, έλεγχος callback και endpoints, αποδοχή και έγκριση. Οι περιγραφές διαπιστευτηρίων Viva διαφέρουν· η επιστροφή Skrill δεν υποστηρίζεται στον ελεγμένο adapter. <a href="/el/integrations/payment-api-setup.html">Ρύθμιση πληρωμών</a></p><h2 id="μπορουν-πελατες-να-κανουν-κρατηση-απο-την-ιστοσελιδα-μας" tabindex="-1">Μπορούν πελάτες να κάνουν κράτηση από την ιστοσελίδα μας; <a class="header-anchor" href="#μπορουν-πελατες-να-κανουν-κρατηση-απο-την-ιστοσελιδα-μας" aria-label="Permalink to &quot;Μπορούν πελάτες να κάνουν κράτηση από την ιστοσελίδα μας;&quot;">​</a></h2><p>Υπάρχουν ανεξάρτητη πύλη και ροή δημοσίευσης στον κώδικα. Η δημόσια λήψη παραμένει ανενεργή μέχρι ρητή έγκριση. Προεπισκόπηση ή ενεργή εγγραφή καναλιού δεν ενεργοποιεί κρατήσεις. <a href="/el/plus/customer-booking-gateway.html">Πύλη πελατών</a></p><h2 id="το-god-s-eye-παρακολουθει-αυτοματα-καθε-οδηγο-και-πτηση" tabindex="-1">Το God&#39;s Eye παρακολουθεί αυτόματα κάθε οδηγό και πτήση; <a class="header-anchor" href="#το-god-s-eye-παρακολουθει-αυτοματα-καθε-οδηγο-και-πτηση" aria-label="Permalink to &quot;Το God&#39;s Eye παρακολουθεί αυτόματα κάθε οδηγό και πτήση;&quot;">​</a></h2><p>Η έκδοση περιλαμβάνει τοπική γεωγραφική απεικόνιση, εξουσιοδοτημένη κοινοποίηση GPS εντός βάρδιας και μόνιμες χειροκίνητες παρατηρήσεις πτήσεων/πλοίων. Εκκρεμούν αδειοδοτημένοι χάρτες, φυσικός έλεγχος GPS, αυτόματη εξωτερική παρακολούθηση και προγραμματισμός. <a href="/el/integrations/live-tracking.html">Στόλος</a> και <a href="/el/plus/arrival-intelligence.html">Αφίξεις</a></p><h2 id="ειναι-ηδη-συνδεδεμενα-whatsapp-email-sms-και-ai" tabindex="-1">Είναι ήδη συνδεδεμένα WhatsApp, email, SMS και AI; <a class="header-anchor" href="#ειναι-ηδη-συνδεδεμενα-whatsapp-email-sms-και-ai" aria-label="Permalink to &quot;Είναι ήδη συνδεδεμένα WhatsApp, email, SMS και AI;&quot;">​</a></h2><p>Υπάρχουν adapters και βάσεις συνομιλιών· εξωτερική αποστολή και χρήση παρόχου απαιτούν χωριστή ρύθμιση και έγκριση. Προεπισκόπηση δεν είναι παράδοση και προσχέδιο AI δεν είναι κράτηση. <a href="/el/integrations/ai-messaging-setup.html">AI και μηνύματα</a></p><h2 id="μπορουμε-να-αναθεσουμε-μεταφορα-σε-αλλη-εταιρεια" tabindex="-1">Μπορούμε να αναθέσουμε μεταφορά σε άλλη εταιρεία; <a class="header-anchor" href="#μπορουμε-να-αναθεσουμε-μεταφορα-σε-αλλη-εταιρεια" aria-label="Permalink to &quot;Μπορούμε να αναθέσουμε μεταφορά σε άλλη εταιρεία;&quot;">​</a></h2><p>Υλοποιούνται μόνιμες αναθέσεις υπεργολάβων και διακανονισμοί. Ελέγξτε εγκεκριμένη σχέση, σκέλος, ποσό και πραγματικό διακανονισμό. Δεν πρόκειται για αυτόματη εξωτερική ανάθεση. <a href="/el/plus/subcontractors.html">Υπεργολάβοι</a></p><h2 id="υποβαλλει-ζωντανα-εγγραφα-mydata-η-edxeix" tabindex="-1">Υποβάλλει ζωντανά έγγραφα myDATA ή EDXEIX; <a class="header-anchor" href="#υποβαλλει-ζωντανα-εγγραφα-mydata-η-edxeix" aria-label="Permalink to &quot;Υποβάλλει ζωντανά έγγραφα myDATA ή EDXEIX;&quot;">​</a></h2><p>Όχι. Η τεκμηριωμένη έκδοση διαθέτει μόνιμες δοκιμαστικές εγγραφές και αποκλείει ζωντανή υποβολή. Ακολουθήστε εγκεκριμένες νόμιμες διαδικασίες και χωριστή αποδοχή. <a href="/el/integrations/regulatory-sandbox.html">Κανονιστικό sandbox</a></p><h2 id="τι-κανω-μετα-απο-timeout-κρατησης-η-πληρωμης" tabindex="-1">Τι κάνω μετά από timeout κράτησης ή πληρωμής; <a class="header-anchor" href="#τι-κανω-μετα-απο-timeout-κρατησης-η-πληρωμης" aria-label="Permalink to &quot;Τι κάνω μετά από timeout κράτησης ή πληρωμής;&quot;">​</a></h2><p>Μην επαναλαμβάνετε τυφλά. Αναζητήστε υπάρχουσα αναφορά και επαληθεύστε έγκυρες εγγραφές κράτησης ή πληρωμής. Κλιμακώστε αβεβαιότητα στον εξουσιοδοτημένο υπεύθυνο. <a href="/el/developers/idempotency.html">Ασφαλής επανάληψη</a> και <a href="/el/tutorials/payment-review.html">Έλεγχος πληρωμής</a></p><h2 id="πως-ενημερωνουμε-η-επαναφερουμε-το-συστημα" tabindex="-1">Πώς ενημερώνουμε ή επαναφέρουμε το σύστημα; <a class="header-anchor" href="#πως-ενημερωνουμε-η-επαναφερουμε-το-συστημα" aria-label="Permalink to &quot;Πώς ενημερώνουμε ή επαναφέρουμε το σύστημα;&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένη διαδικασία έκδοσης και επαληθευμένο σχέδιο αντιγράφων/ανάκτησης. Ο προστατευμένος updater staging δεν αποτελεί γενική άδεια εμπορικής αναβάθμισης. <a href="/el/plus/software-update-manager.html">Ενημερώσεις</a> και <a href="/el/getting-started/backup-recovery.html">Ανάκτηση</a></p><h2 id="σημαινει-100-ενταξη-οτι-μπορουμε-να-ξεκινησουμε" tabindex="-1">Σημαίνει 100% ένταξη ότι μπορούμε να ξεκινήσουμε; <a class="header-anchor" href="#σημαινει-100-ενταξη-οτι-μπορουμε-να-ξεκινησουμε" aria-label="Permalink to &quot;Σημαίνει 100% ένταξη ότι μπορούμε να ξεκινήσουμε;&quot;">​</a></h2><p>Όχι. Η ετοιμότητα ρυθμίσεων διαφέρει από αποδοχή εφαρμογής, πραγματικές δοκιμές πρόσβασης, έγκριση παρόχων και επιχειρησιακή έγκριση. <a href="/el/getting-started/go-live-checklist.html">Λίστα έναρξης</a></p><p>Δείτε <a href="/el/help/feature-availability.html">διαθεσιμότητα</a> και <a href="/el/help/glossary.html">γλωσσάρι</a>.</p>',37)])])}const u=e(i,[["render",h]]);export{c as __pageData,u as default};
